<?php
session_start();require_once '../conexion.php';if(!isset($_SESSION['usuario_id'])||$_SESSION['rol']!=='admin'){header('Location: ../login.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$ci=trim($_POST['ci']??'');$usuario=trim($_POST['usuario']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$hora=$_POST['hora_ingreso']??'08:00';if($ci===''||$usuario===''||$email===''||$password==='')$error='Completá todos los campos.';else{$conexion->begin_transaction();try{$rol='Operario';$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$conexion->prepare("INSERT INTO Persona (CI,usuario,email,`contraseña`,Rol) VALUES (?,?,?,?,?)");$stmt->bind_param('sssss',$ci,$usuario,$email,$hash,$rol);$stmt->execute();$estado='Activo';$stmt=$conexion->prepare("INSERT INTO Operario (CI,Estado,hora_ingreso) VALUES (?,?,?)");$stmt->bind_param('sss',$ci,$estado,$hora);$stmt->execute();$conexion->commit();header('Location: operarios.php?mensaje='.urlencode('Operario agregado correctamente.'));exit;}catch(Throwable $e){$conexion->rollback();$error='No se pudo crear: '.$e->getMessage();}}}
?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agregar operario</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../CSS/sistema.css"></head><body class="sistema-body"><main class="admin-container"><a href="operarios.php" class="volver-link">← Volver</a><section class="dashboard-header"><h1>Agregar operario</h1></section><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><div class="form-sistema-card"><form method="POST"><div class="mb-3"><label>CI (8 dígitos)</label><input name="ci" maxlength="8" class="form-control" required></div><div class="mb-3"><label>Usuario / nombre</label><input name="usuario" class="form-control" required></div><div class="mb-3"><label>Email</label><input type="email" name="email" class="form-control" required></div><div class="mb-3"><label>Contraseña</label><input type="password" name="password" class="form-control" required></div><div class="mb-4"><label>Hora de ingreso</label><input type="time" name="hora_ingreso" value="08:00" class="form-control" required></div><button class="btn-picking">Crear operario</button></form></div></main></body></html>